/* Offline behaviour tests for the rendered service worker.
 *
 * The service worker in web/sw.js is generated by tools/build_offline.py from
 * tools/sw_template.js. These tests load the RENDERED file into a fake worker
 * environment (self, caches, fetch, Response) and drive its install/fetch
 * handlers, so they assert real offline behaviour rather than the source shape.
 */
const { test } = require('node:test');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const ROOT = path.resolve(__dirname, '..');
const WEB = path.join(ROOT, 'web');
const SW_PATH = path.join(WEB, 'sw.js');
const MANIFEST_PATH = path.join(WEB, 'offline-assets.json');
const SCOPE = 'https://example.test/bayan/';
const EXCLUDE = new Set(['sw.js', 'offline-assets.json']);

const SW_SOURCE = fs.readFileSync(SW_PATH, 'utf8');
const MANIFEST = JSON.parse(fs.readFileSync(MANIFEST_PATH, 'utf8'));
const MANIFEST_URLS = MANIFEST.files.map((f) => f.url);

function response(body, { ok = true, status = 200 } = {}) {
  return {
    ok,
    status,
    body,
    clone() { return response(body, { ok, status }); },
    async arrayBuffer() { return body; },
  };
}

function loadWorker({ reachable = MANIFEST_URLS, online = true, seed = {} } = {}) {
  const stores = new Map();
  const handlers = new Map();
  const reach = new Set(reachable);

  function openStore(name) {
    if (!stores.has(name)) stores.set(name, new Map());
    const store = stores.get(name);
    const key = (url) => new URL(String(url), SCOPE).href;
    return {
      async put(url, value) { store.set(key(url), value); },
      async match(url) {
        const target = key(url);
        if (store.has(target)) return store.get(target);
        return undefined;
      },
      async keys() { return [...store.keys()]; },
      async delete(url) { return store.delete(key(url)); },
    };
  }

  const context = {
    URL,
    console: { warn() {}, log() {}, error() {} },
    Blob: class Blob { constructor(parts) { this.parts = parts; } },
    Response: class Response {
      constructor(body, init = {}) {
        this.body = body;
        this.status = init.status || 200;
        this.ok = this.status < 400;
        this.headers = init.headers || {};
      }
    },
    caches: {
      open: async (name) => openStore(name),
      keys: async () => [...stores.keys()],
      delete: async (name) => stores.delete(name),
    },
    fetch: async (input) => {
      if (!online) throw new Error('network down');
      const url = typeof input === 'string' ? input : input.url;
      if (!reach.has(url)) return response(null, { ok: false, status: 404 });
      return response(new Uint8Array([7, 7, 7]));
    },
    location: { href: SCOPE + 'sw.js', origin: 'https://example.test', pathname: '/bayan/sw.js' },
    addEventListener(type, handler) { handlers.set(type, handler); },
    skipWaiting: async () => {},
    clients: { claim: async () => {} },
  };
  context.self = context;
  vm.createContext(context);
  vm.runInContext(SW_SOURCE, context, { filename: 'sw.js' });

  for (const [name, entries] of Object.entries(seed)) {
    const store = stores.get(name) || new Map();
    if (entries instanceof Map) {
      for (const [url, value] of entries) store.set(url, value);
    } else {
      for (const [url, value] of Object.entries(entries)) store.set(new URL(url, SCOPE).href, value);
    }
    stores.set(name, store);
  }

  async function fire(type, event) {
    const handler = handlers.get(type);
    const waits = [];
    handler(Object.assign({ waitUntil: (p) => waits.push(p) }, event));
    await Promise.all(waits);
  }

  return { context, stores, fire, openStore };
}

function cachedKeys(worker, cacheName) {
  const store = worker.stores.get(cacheName);
  return store ? [...store.keys()] : [];
}

test('rendered worker has no template placeholders and lists the whole manifest', () => {
  assert.doesNotMatch(SW_SOURCE, /__FILES__|__VERSION__/);
  for (const url of MANIFEST_URLS) {
    assert.ok(SW_SOURCE.includes(JSON.stringify(url)), `worker does not list ${url}`);
  }
});

test('manifest covers every shipped asset with a matching sha256', () => {
  const onDisk = [];
  (function walk(dir) {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        if (entry.name !== '__pycache__') walk(full);
      } else if (!EXCLUDE.has(entry.name)) {
        onDisk.push(path.relative(WEB, full).split(path.sep).join('/'));
      }
    }
  })(WEB);
  assert.deepEqual([...onDisk].sort(), [...MANIFEST_URLS].sort());
  for (const entry of MANIFEST.files) {
    const digest = crypto.createHash('sha256').update(fs.readFileSync(path.join(WEB, entry.url))).digest('hex');
    assert.equal(digest, entry.integrity, `integrity mismatch for ${entry.url}`);
  }
});

test('install caches every manifest file, then claims clients', async () => {
  const worker = loadWorker();
  await worker.fire('install', {});
  const cacheName = Object.keys(Object.fromEntries(worker.stores))[0];
  const keys = cachedKeys(worker, cacheName);
  assert.equal(keys.length, MANIFEST_URLS.length);
  for (const url of MANIFEST_URLS) {
    assert.ok(keys.includes(new URL(url, SCOPE).href), `not cached: ${url}`);
  }
});

test('a missing file aborts the install and leaves the previous copy intact', async () => {
  const worker = loadWorker({ reachable: MANIFEST_URLS.filter((u) => u !== 'js/app.js') });
  const previous = 'bayan-app-previous';
  const store = worker.stores.get(previous) || new Map();
  store.set(new URL('index.html', SCOPE).href, response(new Uint8Array([1])));
  worker.stores.set(previous, store);
  await worker.fire('install', {});
  const previousKeys = cachedKeys(worker, previous);
  assert.deepEqual(previousKeys, [new URL('index.html', SCOPE).href]);
  const newCaches = [...worker.stores.keys()].filter((k) => k !== previous);
  for (const name of newCaches) {
    const cached = cachedKeys(worker, name).filter((k) => k.endsWith('/js/app.js'));
    assert.equal(cached.length, 0, 'partial install must not register the missing file');
  }
});

test('assets are served from the cache while the network is down', async () => {
  const worker = loadWorker();
  await worker.fire('install', {});
  const cacheName = Object.keys(Object.fromEntries(worker.stores))[0];
  worker.stores.get(cacheName).set(new URL('css/style.css', SCOPE).href, response(new Uint8Array([9, 9])));
  const offline = loadWorker({ online: false, seed: Object.fromEntries(worker.stores) });
  let served;
  await offline.fire('fetch', {
    request: { method: 'GET', mode: 'no-cors', url: SCOPE + 'css/style.css' },
    respondWith: (p) => { served = p; },
  });
  const result = await served;
  assert.equal(result.status, 200);
  assert.deepEqual([...result.body], [9, 9]);
});

test('offline navigation falls back to the cached shell', async () => {
  const worker = loadWorker();
  await worker.fire('install', {});
  const offline = loadWorker({ online: false, seed: Object.fromEntries(worker.stores) });
  let served;
  await offline.fire('fetch', {
    request: { method: 'GET', mode: 'navigate', url: SCOPE + 'lesson' },
    respondWith: (p) => { served = p; },
  });
  const result = await served;
  assert.equal(result.status, 200);
  assert.ok(result.body instanceof Uint8Array, 'expected the cached shell bytes');
});

test('requests outside the worker scope, cross-origin and non-GET are ignored', async () => {
  const worker = loadWorker();
  const cases = [
    { method: 'POST', mode: 'no-cors', url: SCOPE + 'api/progress' },
    { method: 'GET', mode: 'no-cors', url: 'https://other.test/bayan/js/app.js' },
    { method: 'GET', mode: 'no-cors', url: 'https://example.test/elsewhere/app.js' },
  ];
  for (const request of cases) {
    let intercepted = false;
    await worker.fire('fetch', { request, respondWith: () => { intercepted = true; } });
    assert.equal(intercepted, false, `should not intercept ${request.method} ${request.url}`);
  }
});

test('activation drops stale bayan caches and keeps the current one', async () => {
  const worker = loadWorker();
  await worker.fire('install', {});
  const current = Object.keys(Object.fromEntries(worker.stores))[0];
  worker.stores.set('bayan-app-stale', new Map());
  worker.stores.set('unrelated-cache', new Map());
  await worker.fire('activate', {});
  const names = [...worker.stores.keys()];
  assert.ok(names.includes(current), 'current cache must survive');
  assert.ok(!names.includes('bayan-app-stale'), 'stale bayan cache must be dropped');
  assert.ok(names.includes('unrelated-cache'), 'foreign caches must not be touched');
});
